{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Pridopidine, a close N-propylamine analogue, showed high oral availability and linear kinetics in humans after 20–120 mg doses, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Alpidem, an N,N-dipropyl-substituted aromatic drug, had an absolute oral bioavailability of 32 ± 2% in young human subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PNU-96391, a propylpiperidine analogue, had an absolute oral bioavailability of 0.6 (60%) in healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Etodolac had an absolute bioavailability of 0.80 in humans, supporting high F despite containing a carboxylic acid group.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tasimelteon had a mean absolute bioavailability of approximately 38% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Meptazinol had low absolute oral bioavailability (~9%, range 2–19%) in healthy volunteers, providing contradictory evidence; however, its low F is associated with extensive first-pass metabolism of its phenolic group, a feature absent in the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The preponderance of high-transfer human absolute bioavailability data (pridopidine, alpidem, PNU-96391, etodolac, tasimelteon) supports F ≥ 20%. The only low-F analogue, meptazinol, is mechanistically tied to phenolic glucuronidation absent in the query, so it does not overturn the supportive evidence. Therefore, the query is predicted to have high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is present in the provided evidence.",
    "The exact extent of first-pass metabolism of the query's lactam/tertiary amine in humans is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

